import json
import os

chapter_id = "gseb_class10_maths_ch3"
output_file = f"/home/ubuntu/Shine_Academy_Naroda/app_core/assessment/{chapter_id}_questions.json"
os.makedirs(os.path.dirname(output_file), exist_ok=True)

questions = []

def add_q(qid, q_en, q_hi, options_en, options_hi, correct_idx, exp_en, exp_hi, distractor_en, distractor_hi, hint_en, hint_hi, diff="Beginner"):
    questions.append({
        "id": f"Q_{chapter_id}_{qid}",
        "chapter_id": chapter_id,
        "topic_id": f"KOBJ_{chapter_id}_PRACTICE",
        "type": "mcq",
        "difficulty": diff,
        "board": ["GSEB", "CBSE"],
        "marks": 1,
        "bloom_taxonomy": "Applying",
        "question_text": {"english": q_en, "hindi": q_hi},
        "options": [{"english": options_en[i], "hindi": options_hi[i]} for i in range(len(options_en))],
        "correct_index": correct_idx,
        "explanation": {"english": exp_en, "hindi": exp_hi},
        "distractor_rationale": {"english": distractor_en, "hindi": distractor_hi},
        "ai_context": {"hint": hint_en, "hint_hi": hint_hi}
    })

# --- Question 1-20 (Pair of Linear Equations) ---
add_q("001", "The pair of equations 5x - 15y = 8 and 3x - 9y = 24/5 has:", "समीकरणों के युग्म 5x - 15y = 8 और 3x - 9y = 24/5 के कितने हल हैं?", ["One solution", "Two solutions", "Infinitely many solutions", "No solution"], ["एक हल", "दो हल", "अपरिमित रूप से अनेक हल", "कोई हल नहीं"], 2, "a1/a2 = 5/3. b1/b2 = -15/-9 = 5/3. c1/c2 = 8/(24/5) = 40/24 = 5/3. Since a1/a2 = b1/b2 = c1/c2, the lines are coincident, meaning infinitely many solutions.", "a1/a2 = 5/3. b1/b2 = -15/-9 = 5/3. c1/c2 = 8/(24/5) = 40/24 = 5/3। चूँकि a1/a2 = b1/b2 = c1/c2, रेखाएँ संपाती हैं, जिसका अर्थ है अपरिमित रूप से अनेक हल।", "Check the ratio carefully. Don't let fractions confuse you.", "अनुपात को ध्यान से देखें। भिन्नों से भ्रमित न हों।", "Compare a1/a2, b1/b2, and c1/c2.", "a1/a2, b1/b2, और c1/c2 की तुलना करें।")

add_q("002", "If a pair of linear equations is consistent, then the lines will be:", "यदि रैखिक समीकरणों का एक युग्म संगत (consistent) है, तो रेखाएँ होंगी:", ["parallel", "always coincident", "intersecting or coincident", "always intersecting"], ["समानांतर", "हमेशा संपाती", "प्रतिच्छेदी या संपाती", "हमेशा प्रतिच्छेदी"], 2, "Consistent means it has at least one solution. Intersecting lines have 1 solution, coincident lines have infinite solutions.", "संगत का अर्थ है कि इसका कम से कम एक हल है। प्रतिच्छेदी रेखाओं का 1 हल होता है, संपाती रेखाओं के अनंत हल होते हैं।", "Don't forget coincident lines also have solutions.", "यह न भूलें कि संपाती रेखाओं के भी हल होते हैं।", "What does 'consistent' mean?", "'संगत (consistent)' का क्या अर्थ है?")

add_q("003", "For what value of k do the equations 3x - y + 8 = 0 and 6x - ky = -16 represent coincident lines?", "k के किस मान के लिए समीकरण 3x - y + 8 = 0 और 6x - ky = -16 संपाती रेखाओं को दर्शाते हैं?", ["1/2", "-1/2", "2", "-2"], ["1/2", "-1/2", "2", "-2"], 2, "Rewrite 6x - ky = -16 as 6x - ky + 16 = 0. For coincident lines, a1/a2 = b1/b2 = c1/c2. So 3/6 = -1/-k = 8/16. => 1/2 = 1/k = 1/2. Therefore, k = 2.", "6x - ky = -16 को 6x - ky + 16 = 0 के रूप में फिर से लिखें। संपाती रेखाओं के लिए, a1/a2 = b1/b2 = c1/c2। इसलिए 3/6 = -1/-k = 8/16। => 1/2 = 1/k = 1/2। इसलिए, k = 2।", "Make sure all terms are on the same side of the = sign before comparing c1 and c2.", "c1 और c2 की तुलना करने से पहले सुनिश्चित करें कि सभी पद = चिह्न के एक ही तरफ हैं।", "Set a1/a2 = b1/b2.", "a1/a2 = b1/b2 रखें।")

add_q("004", "The pair of equations x = a and y = b graphically represents lines which are:", "समीकरणों का युग्म x = a और y = b ग्राफीय रूप से उन रेखाओं को दर्शाता है जो हैं:", ["parallel", "intersecting at (b, a)", "coincident", "intersecting at (a, b)"], ["समानांतर", "(b, a) पर प्रतिच्छेदी", "संपाती", "(a, b) पर प्रतिच्छेदी"], 3, "x = a is a vertical line. y = b is a horizontal line. They intersect exactly at the point (a, b).", "x = a एक ऊर्ध्वाधर रेखा है। y = b एक क्षैतिज रेखा है। वे ठीक बिंदु (a, b) पर प्रतिच्छेद करते हैं।", "Order matters in coordinates (x, y).", "निर्देशांक (x, y) में क्रम मायने रखता है।", "Draw a quick sketch of x=a and y=b.", "x=a और y=b का एक त्वरित चित्र बनाएं।")

add_q("005", "Half the perimeter of a rectangular garden, whose length is 4m more than its width, is 36m. Find the dimensions.", "एक आयताकार बगीचे के परिमाप का आधा, जिसकी लंबाई उसकी चौड़ाई से 4 मीटर अधिक है, 36 मीटर है। विमाएँ (लम्बाई और चौड़ाई) ज्ञात कीजिए।", ["Length=20m, Width=16m", "Length=16m, Width=20m", "Length=18m, Width=14m", "Length=24m, Width=12m"], ["लंबाई=20m, चौड़ाई=16m", "लंबाई=16m, चौड़ाई=20m", "लंबाई=18m, चौड़ाई=14m", "लंबाई=24m, चौड़ाई=12m"], 0, "Let length=l, width=w. l = w+4. Half perimeter = (2l+2w)/2 = l+w = 36. Substituting l: (w+4)+w = 36 => 2w = 32 => w=16. Then l = 20.", "माना लंबाई=l, चौड़ाई=w। l = w+4। आधा परिमाप = (2l+2w)/2 = l+w = 36। l को प्रतिस्थापित करने पर: (w+4)+w = 36 => 2w = 32 => w=16। फिर l = 20।", "Read carefully: half the perimeter, not full perimeter.", "ध्यान से पढ़ें: परिमाप का आधा, पूरा परिमाप नहीं।", "Form two equations and substitute.", "दो समीकरण बनाएँ और प्रतिस्थापित करें।")

add_q("006", "One equation of a pair of dependent linear equations is -5x + 7y = 2. The second equation can be:", "आश्रित रैखिक समीकरणों के एक युग्म का एक समीकरण -5x + 7y = 2 है। दूसरा समीकरण हो सकता है:", ["10x + 14y + 4 = 0", "-10x - 14y + 4 = 0", "-10x + 14y + 4 = 0", "10x - 14y = -4"], ["10x + 14y + 4 = 0", "-10x - 14y + 4 = 0", "-10x + 14y + 4 = 0", "10x - 14y = -4"], 3, "Dependent means coincident (all ratios equal). Multiply by -2: 10x - 14y = -4. This matches exactly.", "आश्रित का अर्थ है संपाती (सभी अनुपात समान)। -2 से गुणा करें: 10x - 14y = -4। यह बिल्कुल मेल खाता है।", "Check signs carefully after multiplying.", "गुणा करने के बाद चिह्नों की सावधानीपूर्वक जाँच करें।", "Multiply the whole equation by a constant.", "पूरे समीकरण को एक स्थिरांक से गुणा करें।")

add_q("007", "A fraction becomes 1/3 when 1 is subtracted from the numerator and it becomes 1/4 when 8 is added to its denominator. Find the fraction.", "एक भिन्न 1/3 हो जाता है जब उसके अंश से 1 घटाया जाता है और यह 1/4 हो जाता है जब उसके हर में 8 जोड़ा जाता है। भिन्न ज्ञात कीजिए।", ["5/12", "7/15", "5/14", "9/12"], ["5/12", "7/15", "5/14", "9/12"], 0, "Let fraction be x/y. (x-1)/y = 1/3 => 3x-y=3. x/(y+8) = 1/4 => 4x-y=8. Subtracting first from second: x = 5. Then 3(5)-y=3 => 15-3=y => y=12. Fraction is 5/12.", "माना भिन्न x/y है। (x-1)/y = 1/3 => 3x-y=3। x/(y+8) = 1/4 => 4x-y=8। दूसरे में से पहला घटाने पर: x = 5। फिर 3(5)-y=3 => 15-3=y => y=12। भिन्न 5/12 है।", "Just test the options if you are stuck!", "यदि आप अटक गए हैं तो बस विकल्पों का परीक्षण करें!", "Form equations (x-1)/y = 1/3 and x/(y+8) = 1/4", "समीकरण बनाएँ (x-1)/y = 1/3 और x/(y+8) = 1/4")

add_q("008", "Five years ago, Nuri was thrice as old as Sonu. Ten years later, Nuri will be twice as old as Sonu. How old is Nuri now?", "पांच साल पहले, नूरी की उम्र सोनू की उम्र की तीन गुनी थी। दस साल बाद, नूरी की उम्र सोनू की उम्र की दोगुनी होगी। अब नूरी की उम्र क्या है?", ["40 years", "50 years", "60 years", "45 years"], ["40 वर्ष", "50 वर्ष", "60 वर्ष", "45 वर्ष"], 1, "N-5 = 3(S-5) => N-3S = -10. N+10 = 2(S+10) => N-2S = 10. Subtract equations: -S = -20 => S=20. N-2(20) = 10 => N=50.", "N-5 = 3(S-5) => N-3S = -10। N+10 = 2(S+10) => N-2S = 10। समीकरणों को घटाने पर: -S = -20 => S=20। N-2(20) = 10 => N=50।", "Don't forget to add/subtract the years from both people.", "दोनों लोगों की उम्र से वर्षों को जोड़ना/घटाना न भूलें।", "Write equations for N-5 and N+10.", "N-5 और N+10 के लिए समीकरण लिखें।")

add_q("009", "If x = a, y = b is the solution of the equations x - y = 2 and x + y = 4, then the values of a and b are:", "यदि x = a, y = b समीकरणों x - y = 2 और x + y = 4 का हल है, तो a और b के मान हैं:", ["3 and 5", "5 and 3", "3 and 1", "-1 and -3"], ["3 और 5", "5 और 3", "3 और 1", "-1 और -3"], 2, "Adding equations: 2x = 6 => x=3. Substituting x: 3 + y = 4 => y=1. So a=3, b=1.", "समीकरणों को जोड़ने पर: 2x = 6 => x=3। x को प्रतिस्थापित करने पर: 3 + y = 4 => y=1। इसलिए a=3, b=1।", "Just solve them using elimination.", "बस विलोपन विधि (elimination) का उपयोग करके उन्हें हल करें।", "Add both equations together.", "दोनों समीकरणों को एक साथ जोड़ें।")

add_q("010", "The sum of the digits of a two-digit number is 9. Also, nine times this number is twice the number obtained by reversing the order of the digits. Find the number.", "दो अंकों की एक संख्या के अंकों का योग 9 है। साथ ही, इस संख्या का नौ गुना इसके अंकों को उलटने से प्राप्त संख्या का दोगुना है। संख्या ज्ञात कीजिए।", ["18", "27", "36", "45"], ["18", "27", "36", "45"], 0, "Let tens be x, units be y. x+y=9. Number is 10x+y. Reversed is 10y+x. 9(10x+y) = 2(10y+x) => 90x+9y = 20y+2x => 88x = 11y => 8x=y. Substitute y=8x into x+y=9 => 9x=9 => x=1, y=8. Number is 18.", "माना दहाई x है, इकाई y है। x+y=9। संख्या 10x+y है। उलटी संख्या 10y+x है। 9(10x+y) = 2(10y+x) => 90x+9y = 20y+2x => 88x = 11y => 8x=y। y=8x को x+y=9 में प्रतिस्थापित करें => 9x=9 => x=1, y=8। संख्या 18 है।", "A two-digit number xy is written mathematically as 10x+y.", "दो अंकों की संख्या xy को गणितीय रूप से 10x+y के रूप में लिखा जाता है।", "Write the number as 10x + y.", "संख्या को 10x + y के रूप में लिखें।")

add_q("011", "For what value of p does the pair of equations 4x + py + 8 = 0 and 2x + 2y + 2 = 0 have unique solution?", "p के किस मान के लिए समीकरण 4x + py + 8 = 0 और 2x + 2y + 2 = 0 का एक अद्वितीय हल है?", ["p = 4", "p ≠ 4", "p = 2", "p ≠ 2"], ["p = 4", "p ≠ 4", "p = 2", "p ≠ 2"], 1, "For unique solution, a1/a2 ≠ b1/b2. So 4/2 ≠ p/2 => 2 ≠ p/2 => p ≠ 4.", "अद्वितीय हल के लिए, a1/a2 ≠ b1/b2। इसलिए 4/2 ≠ p/2 => 2 ≠ p/2 => p ≠ 4।", "Unique solution means intersecting lines.", "अद्वितीय हल का अर्थ प्रतिच्छेदी रेखाएँ हैं।", "Use a1/a2 ≠ b1/b2.", "a1/a2 ≠ b1/b2 का प्रयोग करें।")

add_q("012", "The pair of equations x = 0 and x = 5 has:", "समीकरणों के युग्म x = 0 और x = 5 के कितने हल हैं?", ["No solution", "One solution", "Two solutions", "Infinitely many solutions"], ["कोई हल नहीं", "एक हल", "दो हल", "अपरिमित रूप से अनेक हल"], 0, "x=0 is the y-axis, and x=5 is a vertical line parallel to the y-axis. They never intersect.", "x=0 y-अक्ष है, और x=5 y-अक्ष के समानांतर एक ऊर्ध्वाधर रेखा है। वे कभी प्रतिच्छेद नहीं करते हैं।", "Vertical lines are parallel to each other.", "ऊर्ध्वाधर रेखाएँ एक-दूसरे के समानांतर होती हैं।", "Are these lines parallel or intersecting?", "क्या ये रेखाएँ समानांतर हैं या प्रतिच्छेदी?")

add_q("013", "Find the value of k for which the system kx - y = 2 and 6x - 2y = 3 has a unique solution.", "k का मान ज्ञात कीजिए जिसके लिए निकाय kx - y = 2 और 6x - 2y = 3 का एक अद्वितीय हल है।", ["k = 3", "k ≠ 3", "k ≠ 0", "k = 0"], ["k = 3", "k ≠ 3", "k ≠ 0", "k = 0"], 1, "For unique solution, a1/a2 ≠ b1/b2 => k/6 ≠ -1/-2 => k/6 ≠ 1/2 => k ≠ 3.", "अद्वितीय हल के लिए, a1/a2 ≠ b1/b2 => k/6 ≠ -1/-2 => k/6 ≠ 1/2 => k ≠ 3।", "Make sure you include the negative signs for b1 and b2.", "सुनिश्चित करें कि आप b1 और b2 के लिए ऋणात्मक चिह्न शामिल करते हैं।", "Apply the unique solution condition.", "अद्वितीय हल की शर्त लागू करें।")

add_q("014", "A boat goes 16 km upstream and 24 km downstream in 6 hours. What type of equations will this form?", "एक नाव 6 घंटे में 16 किमी धारा के प्रतिकूल (upstream) और 24 किमी धारा के अनुकूल (downstream) जाती है। यह किस प्रकार के समीकरण बनाएगी?", ["Linear equations", "Quadratic equations", "Equations reducible to linear form", "None of these"], ["रैखिक समीकरण", "द्विघात समीकरण", "रैखिक रूप में परिवर्तनशील समीकरण", "इनमें से कोई नहीं"], 2, "Let speed of boat be x, stream be y. 16/(x-y) + 24/(x+y) = 6. Variables are in denominator, so it's reducible to linear form.", "माना नाव की गति x है, धारा की गति y है। 16/(x-y) + 24/(x+y) = 6। चर हर (denominator) में हैं, इसलिए यह रैखिक रूप में परिवर्तनशील है।", "Think about the formula: Time = Distance / Speed.", "सूत्र के बारे में सोचें: समय = दूरी / गति।", "Where do the variables 'x' and 'y' appear in the equation?", "समीकरण में चर 'x' और 'y' कहाँ दिखाई देते हैं?")

add_q("015", "If the lines given by 3x + 2ky = 2 and 2x + 5y + 1 = 0 are parallel, then the value of k is:", "यदि 3x + 2ky = 2 और 2x + 5y + 1 = 0 द्वारा दी गई रेखाएँ समानांतर हैं, तो k का मान है:", ["5/4", "2/5", "15/4", "3/2"], ["5/4", "2/5", "15/4", "3/2"], 2, "Parallel means a1/a2 = b1/b2 ≠ c1/c2. So 3/2 = 2k/5 => 15 = 4k => k = 15/4.", "समानांतर का अर्थ है a1/a2 = b1/b2 ≠ c1/c2। इसलिए 3/2 = 2k/5 => 15 = 4k => k = 15/4।", "The constant terms don't need to be checked if you just need k.", "यदि आपको केवल k की आवश्यकता है तो अचर पदों की जाँच करने की आवश्यकता नहीं है।", "Equate the first two ratios.", "पहले दो अनुपातों की तुलना करें।")

add_q("016", "Find the solution: x + y = 14 and x - y = 4.", "हल ज्ञात कीजिए: x + y = 14 और x - y = 4।", ["x=9, y=5", "x=5, y=9", "x=10, y=4", "x=8, y=6"], ["x=9, y=5", "x=5, y=9", "x=10, y=4", "x=8, y=6"], 0, "Adding the equations gives 2x = 18 => x=9. Subtracting gives 2y = 10 => y=5.", "समीकरणों को जोड़ने पर 2x = 18 => x=9 प्राप्त होता है। घटाने पर 2y = 10 => y=5 प्राप्त होता है।", "Elimination method is the fastest here.", "यहाँ विलोपन विधि (Elimination method) सबसे तेज़ है।", "Add the equations.", "समीकरणों को जोड़ें।")

add_q("017", "Ritu can row downstream 20 km in 2 hours, and upstream 4 km in 2 hours. Find her speed of rowing in still water.", "रितु धारा के अनुकूल 2 घंटे में 20 किमी और धारा के प्रतिकूल 2 घंटे में 4 किमी नाव चला सकती है। शांत जल में उसके नाव चलाने की गति ज्ञात कीजिए।", ["6 km/h", "8 km/h", "4 km/h", "10 km/h"], ["6 किमी/घंटा", "8 किमी/घंटा", "4 किमी/घंटा", "10 किमी/घंटा"], 0, "Downstream speed x+y = 20/2 = 10. Upstream speed x-y = 4/2 = 2. Adding them: 2x = 12 => x = 6.", "धारा के अनुकूल गति x+y = 20/2 = 10। धारा के प्रतिकूल गति x-y = 4/2 = 2। उन्हें जोड़ने पर: 2x = 12 => x = 6।", "Speed = Distance / Time.", "गति = दूरी / समय।", "Find the speeds first, then solve for x.", "पहले गति ज्ञात करें, फिर x के लिए हल करें।")

add_q("018", "The father's age is six times his son's age. Four years hence, the age of the father will be four times his son's age. The present ages of the son and the father are, respectively:", "पिता की आयु उसके पुत्र की आयु की छह गुनी है। चार वर्ष बाद, पिता की आयु उसके पुत्र की आयु की चार गुनी होगी। पुत्र और पिता की वर्तमान आयु क्रमशः है:", ["4 and 24", "5 and 30", "6 and 36", "3 and 24"], ["4 और 24", "5 और 30", "6 और 36", "3 और 24"], 2, "Let son=y, father=x. x = 6y. Also, x+4 = 4(y+4). Substitute x: 6y+4 = 4y+16 => 2y=12 => y=6. x = 6(6) = 36.", "माना पुत्र=y, पिता=x। x = 6y। साथ ही, x+4 = 4(y+4)। x को प्रतिस्थापित करें: 6y+4 = 4y+16 => 2y=12 => y=6। x = 6(6) = 36।", "Use substitution method.", "प्रतिस्थापन विधि (substitution method) का उपयोग करें।", "Form an equation for 'four years hence'.", "'चार वर्ष बाद' के लिए एक समीकरण बनाएँ।")

add_q("019", "Which of the following pairs of equations is inconsistent?", "निम्नलिखित में से कौन सा समीकरण युग्म असंगत (inconsistent) है?", ["3x-y=9, x-y/3=3", "4x+3y=24, -2x+3y=6", "5x-y=10, 10x-2y=20", "-2x+y=3, -4x+2y=10"], ["3x-y=9, x-y/3=3", "4x+3y=24, -2x+3y=6", "5x-y=10, 10x-2y=20", "-2x+y=3, -4x+2y=10"], 3, "Inconsistent means parallel lines (a1/a2 = b1/b2 ≠ c1/c2). For option 4: -2/-4 = 1/2, 1/2 = 1/2, 3/10 ≠ 1/2. So they are parallel.", "असंगत का अर्थ है समानांतर रेखाएँ (a1/a2 = b1/b2 ≠ c1/c2)। विकल्प 4 के लिए: -2/-4 = 1/2, 1/2 = 1/2, 3/10 ≠ 1/2। इसलिए वे समानांतर हैं।", "Check the ratio of c1/c2.", "c1/c2 के अनुपात की जाँच करें।", "Look for the option where the first two ratios match but the third doesn't.", "उस विकल्प की तलाश करें जहाँ पहले दो अनुपात मेल खाते हों लेकिन तीसरा न हो।")

add_q("020", "The cost of 5 pens and 8 pencils is Rs 120, while the cost of 8 pens and 5 pencils is Rs 153. Find the cost of 1 pen and 1 pencil.", "5 पेन और 8 पेंसिलों की कीमत 120 रुपये है, जबकि 8 पेन और 5 पेंसिलों की कीमत 153 रुपये है। 1 पेन और 1 पेंसिल की कीमत ज्ञात कीजिए।", ["Pen: 15, Pencil: 6", "Pen: 16, Pencil: 5", "Pen: 17, Pencil: 4", "Pen: 18, Pencil: 3"], ["पेन: 15, पेंसिल: 6", "पेन: 16, पेंसिल: 5", "पेन: 17, पेंसिल: 4", "पेन: 18, पेंसिल: 3"], 1, "5x+8y=120 and 8x+5y=153. Add: 13x+13y=273 => x+y=21. Subtract: -3x+3y=-33 => x-y=11. Adding these new equations: 2x = 32 => x=16, y=5.", "5x+8y=120 और 8x+5y=153। जोड़ें: 13x+13y=273 => x+y=21। घटाएं: -3x+3y=-33 => x-y=11। इन नए समीकरणों को जोड़ने पर: 2x = 32 => x=16, y=5।", "When coefficients are swapped, add and subtract the equations to make them simpler.", "जब गुणांकों की अदला-बदली की जाती है, तो समीकरणों को सरल बनाने के लिए उन्हें जोड़ें और घटाएं।", "Try adding the two equations together first.", "पहले दोनों समीकरणों को एक साथ जोड़ने का प्रयास करें।")

with open(output_file, "w", encoding="utf-8") as f:
    json.dump(questions, f, indent=2, ensure_ascii=False)
